function updateLangCast(lang){
  updateChannelLink(lang);
  var body = document.getElementById('nm-langcast-body');
  if (!body) return;
  var d = LANGCAST[lang] || {links:[],pending:(NEW_LANGUAGE_STATUS[lang]||{}).prep||'In preparation'};
  var html = '';
  for (var i = 0; i < d.links.length; i++){
    html += '<a href="' + d.links[i].u + '" rel="noopener" target="_blank">' + d.links[i].t + ' ↗</a>';
  }
  if (d.pending){ html += '<span class="nm-langcast-pending">' + d.pending + '</span>'; }
  body.innerHTML = html;
  var nv = NAVLANG[lang] || {yt:null,sp:null,pod:null,prep:(NEW_LANGUAGE_STATUS[lang]||{}).prep||'In preparation'};
  var slots = [["nr-link-yt", "yt"], ["nr-link-sp", "sp"], ["nr-link-pod", "pod"]];
  for (var k = 0; k < slots.length; k++){
    var el = document.getElementById(slots[k][0]);
    if (!el) continue;
    if (!el.dataset.origHref){ el.dataset.origHref = el.getAttribute("href"); el.dataset.origText = el.textContent; }
    var dd = nv[slots[k][1]];
    if (dd){
      el.setAttribute("href", dd.u);
      el.textContent = dd.t;
      el.classList.remove("nr-link-disabled");
      el.removeAttribute("aria-disabled");
    } else {
      el.removeAttribute("href");
      var base = slots[k][1] === "yt" ? "YouTube playlist" : (slots[k][1] === "sp" ? "Spotify" : "Podcast");
      el.textContent = base + " - " + nv.prep;
      el.classList.add("nr-link-disabled");
      el.setAttribute("aria-disabled", "true");
    }
  }
}


